CREATE OR REPLACE FUNCTION public.validate_service_source_order() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _s public.services; _manual boolean; BEGIN SELECT * INTO _s FROM public.services WHERE id=NEW.service_id; SELECT manual_control INTO _manual FROM public.categories WHERE id=_s.category_id; IF NOT public.service_source_enabled(_s.provider_id) OR NOT _s.provider_available THEN RAISE EXCEPTION 'SERVICE_UNAVAILABLE'; END IF; IF coalesce(_manual,false) THEN NEW.provider_id:=NULL; NEW.provider_service_id:=NULL; NEW.dispatch_state:='manual'; RETURN NEW; END IF; NEW.provider_id:=_s.provider_id; NEW.provider_service_id:=_s.provider_service_id; IF _s.provider_id IS NOT NULL AND NOT _s.provider_order_supported THEN RAISE EXCEPTION 'SPECIAL_INPUT_REQUIRED'; END IF; IF _s.provider_id IS NOT NULL THEN NEW.dispatch_state:='queued'; END IF; RETURN NEW; END $$;